DAX = [
 ('Cases', 'COUNTROWS(fact_case)', 'fact_case', '#,0', 'D1 D2 D4'),
 ('Open Cases', 'CALCULATE([Cases], fact_case[status] = "Open")', 'fact_case', '#,0', 'D1 D2'),
 ('Closed Cases', 'CALCULATE([Cases], fact_case[status] = "Closed")', 'fact_case', '#,0', 'D2 D4'),
 ('New Cases', 'CALCULATE([Cases], USERELATIONSHIP(fact_case[opened_date], dim_date[Date]))', 'fact_case', '#,0', 'D1'),
 ('New Cases 30d', 'CALCULATE([Cases], fact_case[opened_date] >= TODAY() - 30)', 'fact_case', '#,0', 'D1'),
 ('Hearings Next 30d', 'CALCULATE([Cases], fact_case[status] = "Open", fact_case[next_hearing_date] >= TODAY(), fact_case[next_hearing_date] <= TODAY() + 30)', 'fact_case', '#,0', 'D1'),
 ('Overdue Actions', 'CALCULATE([Cases], fact_case[status] = "Open", fact_case[next_action_due] < TODAY())', 'fact_case', '#,0', 'D1 D2'),
 ('Avg Days Open', 'CALCULATE(AVERAGEX(fact_case, DATEDIFF(fact_case[opened_date], TODAY(), DAY)), fact_case[status] = "Open")', 'fact_case', '#,0', 'D1'),
 ('Avg Days to Close', 'CALCULATE(AVERAGEX(fact_case, DATEDIFF(fact_case[opened_date], fact_case[closed_date], DAY)), fact_case[status] = "Closed")', 'fact_case', '#,0', 'D2 D4'),
 ('Open Cases at Date', 'VAR d = MAX(dim_date[Date]) RETURN CALCULATE(COUNTROWS(fact_case), REMOVEFILTERS(dim_date), fact_case[opened_date] <= d, OR(ISBLANK(fact_case[closed_date]), fact_case[closed_date] > d))', 'fact_case', '#,0', 'D2'),
 ('Claimed', 'SUM(fact_case[claim_amount_aed])', 'fact_case', '#,0', 'D2 D4'),
 ('Awarded', 'SUM(fact_case[awarded_amount_aed])', 'fact_case', '#,0', 'D2'),
 ('Settled', 'SUM(fact_case[settlement_amount_aed])', 'fact_case', '#,0', 'D2'),
 ('Awarded or Settled', '[Awarded] + [Settled]', 'fact_case', '#,0', 'D2'),
 ('Recovered', 'SUM(fact_case[recovered_amount_aed])', 'fact_case', '#,0', 'D2 D4'),
 ('Recovery Rate', 'DIVIDE([Recovered], [Awarded or Settled])', 'fact_case', '0.0%', 'D2'),
 ('Decided Cases', 'CALCULATE([Cases], fact_case[outcome] IN {"Won", "Partially won", "Settled", "Lost", "Takedown achieved"})', 'fact_case', '#,0', 'D2 D4'),
 ('Win Rate', 'DIVIDE(CALCULATE([Cases], fact_case[outcome] IN {"Won", "Partially won", "Settled", "Takedown achieved"}), [Decided Cases])', 'fact_case', '0.0%', 'D2 D4'),
 ('Legal Spend', 'SUM(fact_invoice[amount_aed])', 'fact_invoice', '#,0', 'D2'),
 ('Spend to Recovery', 'DIVIDE([Legal Spend], [Recovered])', 'fact_invoice', '0.00', 'D2'),
 ('Reports', 'COUNTROWS(fact_mailbox)', 'fact_mailbox', '#,0', 'D3'),
 ('Reports 30d', 'CALCULATE([Reports], fact_mailbox[received_at] >= TODAY() - 30)', 'fact_mailbox', '#,0', 'D3'),
 ('Backlog', 'CALCULATE([Reports], fact_mailbox[triage_status] = "New")', 'fact_mailbox', '#,0', 'D3'),
 ('SLA Met %', '1 - DIVIDE(CALCULATE([Reports], fact_mailbox[sla_breached] = TRUE()), CALCULATE([Reports], NOT ISBLANK(fact_mailbox[triaged_at])))', 'fact_mailbox', '0.0%', 'D3'),
 ('Median Hours to Triage', 'MEDIANX(FILTER(fact_mailbox, NOT ISBLANK(fact_mailbox[triaged_at])), DATEDIFF(fact_mailbox[received_at], fact_mailbox[triaged_at], HOUR))', 'fact_mailbox', '#,0', 'D3'),
 ('Conversion to Case %', 'DIVIDE(CALCULATE([Reports], fact_mailbox[triage_status] = "Linked to case"), [Reports])', 'fact_mailbox', '0.0%', 'D3'),
 ('Takedowns Completed', 'CALCULATE(COUNTROWS(fact_appstore), fact_appstore[status] = "Removed")', 'fact_appstore', '#,0', 'D3 D4'),
 ('Takedown Success %', 'DIVIDE([Takedowns Completed], CALCULATE(COUNTROWS(fact_appstore), fact_appstore[status] IN {"Removed", "Rejected by store", "Re-listed", "Takedown requested"}))', 'fact_appstore', '0.0%', 'D3 D4'),
 ('Avg Days to Takedown', 'AVERAGEX(FILTER(fact_appstore, NOT ISBLANK(fact_appstore[removed_date])), DATEDIFF(fact_appstore[takedown_requested_date], fact_appstore[removed_date], DAY))', 'fact_appstore', '#,0', 'D3'),
 ('Active Infringers', 'CALCULATE(DISTINCTCOUNT(fact_case[infringer_id]), fact_case[status] = "Open")', 'fact_case', '#,0', 'D4'),
 ('Repeat Offenders', 'CALCULATE(DISTINCTCOUNT(dim_infringer[infringer_id]), dim_infringer[repeat_offender] = TRUE())', 'dim_infringer', '#,0', 'D4'),
 ('Documents Indexed %', 'DIVIDE(CALCULATE(COUNTROWS(fact_document), fact_document[index_status] IN {"Indexed", "Indexed (flagged)"}), COUNTROWS(fact_document))', 'fact_document', '0.0%', 'DS-1'),
]

